import{_ as n,o as s,c as e,a2 as t}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Architecture Overview","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md","lastUpdated":null}'),r={name:"guide/architecture.md"};function o(i,a,p,l,c,g){return s(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h1><p>OpenFlow is designed as a <strong>modular, concurrent, and protocol-agnostic orchestration engine</strong> written in Golang.</p><hr><h2 id="_1-high-level-architecture-diagram" tabindex="-1">1. High-Level Architecture Diagram <a class="header-anchor" href="#_1-high-level-architecture-diagram" aria-label="Permalink to &quot;1. High-Level Architecture Diagram&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                 ┌──────────────────────────────────────────────┐</span></span>
<span class="line"><span>                 │       OpenFlow Visual Studio &amp; CLI           │</span></span>
<span class="line"><span>                 │    (React Canvas / openflowctl CLI)          │</span></span>
<span class="line"><span>                 └──────────────────────┬───────────────────────┘</span></span>
<span class="line"><span>                                        │ REST / WebSockets / YAML</span></span>
<span class="line"><span>                                        ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                            OpenFlow Core Server                             │</span></span>
<span class="line"><span>│                                                                             │</span></span>
<span class="line"><span>│  ┌───────────────────────┐  ┌──────────────────────┐  ┌──────────────────┐  │</span></span>
<span class="line"><span>│  │   Gin REST API Engine │  │ WebSocket Live Hub   │  │ Prometheus / OTel│  │</span></span>
<span class="line"><span>│  └───────────┬───────────┘  └──────────┬───────────┘  └────────┬─────────┘  │</span></span>
<span class="line"><span>│              │                         │                       │            │</span></span>
<span class="line"><span>│              ▼                         ▼                       ▼            │</span></span>
<span class="line"><span>│  ┌───────────────────────────────────────────────────────────────────────┐  │</span></span>
<span class="line"><span>│  │                   Workflow Execution Engine (Go)                      │  │</span></span>
<span class="line"><span>│  │                                                                       │  │</span></span>
<span class="line"><span>│  │  • Graph Traversal (DAG &amp; BPMN)    • Expression Evaluator (expr-lang) │  │</span></span>
<span class="line"><span>│  │  • Goroutine Concurrency           • Retry Scheduler &amp; Backoff        │  │</span></span>
<span class="line"><span>│  │  • Distributed Saga Manager        • Inbound Trigger Listener         │  │</span></span>
<span class="line"><span>│  └───────────────────────────────────┬───────────────────────────────────┘  │</span></span>
<span class="line"><span>│                                      │                                      │</span></span>
<span class="line"><span>│  ┌───────────────────────────────────┴───────────────────────────────────┐  │</span></span>
<span class="line"><span>│  │                      Pluggable Connector Registry                     │  │</span></span>
<span class="line"><span>│  │                                                                       │  │</span></span>
<span class="line"><span>│  │  [HTTP]  [Kafka]  [RabbitMQ]  [gRPC]  [Postgres]  [WebSocket]  [...] │  │</span></span>
<span class="line"><span>│  └───────────────────────────────────────────────────────────────────────┘  │</span></span>
<span class="line"><span>└──────────────────────────────────────┬──────────────────────────────────────┘</span></span>
<span class="line"><span>                                       │</span></span>
<span class="line"><span>            ┌──────────────────────────┼──────────────────────────┐</span></span>
<span class="line"><span>            ▼                          ▼                          ▼</span></span>
<span class="line"><span>┌───────────────────────┐  ┌───────────────────────┐  ┌───────────────────────┐</span></span>
<span class="line"><span>│ PostgreSQL Store      │  │ Apache Kafka Broker   │  │ RabbitMQ AMQP         │</span></span>
<span class="line"><span>│ (Workflows/Executions)│  │ (Events / Streams)    │  │ (Message Queues)      │</span></span>
<span class="line"><span>└───────────────────────┘  └───────────────────────┘  └───────────────────────┘</span></span></code></pre></div><hr><h2 id="_2-core-subsystems" tabindex="-1">2. Core Subsystems <a class="header-anchor" href="#_2-core-subsystems" aria-label="Permalink to &quot;2. Core Subsystems&quot;">​</a></h2><h3 id="_1-engine-pkg-engine" tabindex="-1">1. Engine (<code>pkg/engine</code>) <a class="header-anchor" href="#_1-engine-pkg-engine" aria-label="Permalink to &quot;1. Engine (\`pkg/engine\`)&quot;">​</a></h3><ul><li><strong>Non-blocking Dispatch</strong>: Dispatches workflow instances in managed goroutines.</li><li><strong>Context Propagation</strong>: Thread-safe variable environment passing between stages.</li><li><strong>Saga Rollback Coordinator</strong>: Tracks executed stages in a LIFO stack and invokes compensating actions backwards upon downstream failure.</li></ul><h3 id="_2-connectors-layer-pkg-connectors" tabindex="-1">2. Connectors Layer (<code>pkg/connectors</code>) <a class="header-anchor" href="#_2-connectors-layer-pkg-connectors" aria-label="Permalink to &quot;2. Connectors Layer (\`pkg/connectors\`)&quot;">​</a></h3><ul><li>Pluggable interface (<code>Connector</code>) allowing any protocol to implement <code>Execute(ctx, execCtx, config, input) (output, error)</code>.</li><li>Connectors can run synchronously or asynchronously with custom timeout deadlines.</li></ul><h3 id="_3-persistence-store-pkg-storage" tabindex="-1">3. Persistence Store (<code>pkg/storage</code>) <a class="header-anchor" href="#_3-persistence-store-pkg-storage" aria-label="Permalink to &quot;3. Persistence Store (\`pkg/storage\`)&quot;">​</a></h3><ul><li><strong>PostgreSQL Store</strong>: Native PostgreSQL driver (<code>github.com/lib/pq</code>) storing workflows, execution steps, and audit logs using PostgreSQL <code>JSONB</code> columns.</li><li><strong>Memory Store</strong>: Concurrent, thread-safe memory storage fallback for development and testing.</li></ul><h3 id="_4-observability-pkg-observability" tabindex="-1">4. Observability (<code>pkg/observability</code>) <a class="header-anchor" href="#_4-observability-pkg-observability" aria-label="Permalink to &quot;4. Observability (\`pkg/observability\`)&quot;">​</a></h3><ul><li><strong>OpenTelemetry Tracer</strong>: Roots and child spans exported to Jaeger via OTLP (<code>OTEL_EXPORTER_OTLP_ENDPOINT</code>).</li><li><strong>Prometheus Metrics</strong>: Scrape endpoint <code>/metrics</code> tracking execution counts, durations, and active gauges.</li></ul>`,15)])])}const h=n(r,[["render",o]]);export{u as __pageData,h as default};
